// src/queries/taskQuery.ts
export function filterTasks(tasks: Task[], filters: { status?: string; priority?: string; tag?: string; search?: string }): Task[] {
  return tasks.filter(task => {
    if (filters.status && task.status !== filters.status) return false;
    if (filters.priority && task.priority !== filters.priority) return false;
    if (filters.tag && !task.tags.includes(filters.tag)) return false;
    if (filters.search) {
      const query = filters.search.toLowerCase();
      if (!task.description.toLowerCase().includes(query) && !JSON.stringify(task.metadata).toLowerCase().includes(query)) return false;
    }
    return true;
  });
}

// In CLI handler
program.command('list').option('--status <value>').action(async (options) => {
  const tasks = await loadAllTasks('tasks.json');
  const filtered = filterTasks(tasks, options);
  console.table(filtered.map(t => ({ id: t.id, status: t.status, priority: t.priority })));
});
